/* Isolated interaction prototype. All records are fictional and reset on reload. */
(() => {
  'use strict';
  const $ = s => document.querySelector(s);
  const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const icon = n => window.HAVEN_ICONS[n] || '';
  const money = n => new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(n);
  let screen = 'stock', selected = 1, cashMode = 'close', guestEdit = false, guestView = false, toastTimer;
  const initial = () => ({stock:[{name:'Bath towels',sku:'LIN-001',qty:24,unit:'pieces',min:8},{name:'Hand towels',sku:'LIN-002',qty:10,unit:'pieces',min:6},{name:'Toiletry kits',sku:'AMN-001',qty:15,unit:'kits',min:8},{name:'Bottled water',sku:'AMN-002',qty:4,unit:'bottles',min:6}],movements:[],shift:{open:true,float:1000,id:1},payments:[{guest:0,amount:1200,method:'Cash',shift:1},{guest:1,amount:800,method:'Cash',shift:1},{guest:2,amount:500,method:'GCash',shift:1}],guests:[{name:'Lara Cruz',room:'204',total:4800,carry:2400},{name:'Miguel Tan',room:'208',total:3000,carry:2200},{name:'Sofia Reyes',room:'305',total:4500,carry:3500}],profile:{name:'Lara Cruz',phone:'0917 000 0000',email:'lara@example.invalid',address:'Sample address, Quezon City'},verified:false,audit:[],requests:[{id:'GR-1042',title:'Extra hand towels',detail:'Room 204 · 2 pieces · Lara Cruz',status:'Pending',owner:'Front desk'},{id:'GR-1038',title:'Air conditioning check',detail:'Room 204 · Lara Cruz',status:'In progress',owner:'Maintenance'},{id:'GR-1034',title:'Extra pillows',detail:'Room 208 · Miguel Tan',status:'Completed',owner:'Housekeeping'}],handovers:[{id:'HO-012',title:'Confirm late arrival time',source:'RSV-1027',owner:'Nina Morales · Front desk',status:'Awaiting acknowledgement',note:'Guest expects to arrive after 10 PM. Confirm the arrival time before shift end.'},{id:'HO-011',title:'Check room 204 readiness',source:'GR-1038',owner:'Alex Reyes · Front desk',status:'Acknowledged',note:'Follow up with maintenance before updating the guest.'}],fail:false,last:null});
  let data = initial();
  const badge = (text,kind='') => `<span class="state-tag ${kind}">${esc(text)}</span>`;
  const button = (text,action,kind='',extra='') => `<button type="button" class="hms-btn ${kind}" data-action="${action}" ${extra}>${text}</button>`;
  const heading = (title,copy,actions='') => `<div class="page-heading"><div><h1>${title}</h1><p>${copy}</p></div><div class="heading-actions">${actions}</div></div>`;
  const panel = (title,copy,body,extra='') => `<section class="panel"><div class="panel-head"><div><h2>${title}</h2><p>${copy}</p></div>${extra}</div><div class="panel-body">${body}</div></section>`;
  const field = (label,name,value='',type='text',extra='') => `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;
  const error = '<p class="inline-error" id="form-error" role="alert" hidden></p>';
  const metrics = entries => `<div class="metric-strip">${entries.map(([value,label])=>`<div class="metric"><strong>${value}</strong><span>${label}</span></div>`).join('')}</div>`;
  const checks = body => `<details class="checks"><summary>Try an edge case <span>Preview controls</span></summary><p>These simulate proposed safeguards using sample records.</p><div>${body}</div></details>`;
  const failCheck = button('Simulate next save failure','fail');
  const formError = text => { const el=$('#form-error'); el.textContent=text; el.hidden=false; };
  function toast(text){clearTimeout(toastTimer);$('#feedback').innerHTML=icon('CircleCheck')+`<span>${esc(text)}</span>`;$('#feedback').hidden=false;toastTimer=setTimeout(()=>$('#feedback').hidden=true,5500);}
  function saveAllowed(){if(!data.fail)return true;data.fail=false;formError('Save unavailable. Your entries are preserved; no records were changed. Try again.');return false;}
  const balance = i => data.guests[i].total-data.guests[i].carry-data.payments.filter(p=>p.guest===i).reduce((s,p)=>s+p.amount,0);
  const expected = () => data.shift.float+data.payments.filter(p=>p.method==='Cash'&&p.shift===data.shift.id).reduce((s,p)=>s+p.amount,0);
  function stock(){const item=data.stock[selected];return heading('Inventory','Issue hotel supplies with a matching stock movement every time.',badge('Housekeeping view','blue'))+metrics([[data.stock.length,'Tracked supplies'],[data.stock.filter(s=>s.qty<s.min).length,'Below minimum'],[data.movements.length,'Movements in this preview']])+`<div class="split"><div class="stack">${panel('Supplies on hand','Select an item to record usage or a count correction.',`<div class="table-wrap"><table><thead><tr><th>Supply</th><th>Available</th><th>Status</th><th><span class="sr-only">Action</span></th></tr></thead><tbody>${data.stock.map((s,i)=>`<tr class="${selected===i?'selected':''}"><td><b>${s.name}</b><small>${s.sku}</small></td><td class="numeric"><b>${s.qty}</b> ${s.unit}</td><td>${badge(s.qty<s.min?'Below minimum':'Available',s.qty<s.min?'warn':'good')}</td><td>${button('Select','select-stock','','data-index="'+i+'"')}</td></tr>`).join('')}</tbody></table></div>`)}${panel('Movement history','The balance and its history are saved as one operation.',data.movements.length?`<ul class="history">${data.movements.slice().reverse().map(m=>`<li>${icon('ArrowUpRight')}<div><b>${esc(m.title)}</b><small>${esc(m.detail)} · Mara Santos · just now</small></div>${badge('Recorded','good')}</li>`).join('')}</ul>`:'<div class="empty-view">'+icon('ClipboardList')+'<h3>No preview movements yet</h3><p>Issue supplies to see the linked record here.</p></div>')}</div><div class="stack">${panel('Record stock movement',item.name+' · '+item.qty+' '+item.unit+' available',`<form id="stock-form"><div class="field"><label for="stock-kind">Movement type</label><select id="stock-kind" name="kind"><option value="issue">Issue supplies</option><option value="count">Correct physical count</option></select></div>${field('Quantity','quantity',2,'number','min="0" step="1" required')}${field('Room / request reference','reference','Room 204 · GR-1042','text','required')}${field('Reason','reason','Guest requested extra supplies','text','required')}<div class="notice">${icon('ShieldCheck')}<span>Insufficient stock blocks the entire save. A correction requires a reason.</span></div>${error}<div class="form-buttons"><button class="hms-btn primary" type="submit">Save movement</button></div></form>`)}${checks(button('Try insufficient stock','insufficient')+failCheck+button('Preview safe stock retry','retry-stock'))}</div></div>`;}
  function cash(){let right;if(cashMode==='collect'){right=panel('Collect payment','One payment updates the folio and creates a receipt.',`<form id="payment-form"><div class="field"><label for="guest">Guest folio</label><select id="guest" name="guest">${data.guests.map((g,i)=>`<option value="${i}" ${i===selected?'selected':''}>${g.name} · ${money(balance(i))} due</option>`).join('')}</select></div>${field('Amount (PHP)','amount',balance(selected),'number','min="0.01" step="0.01" required')}<div class="field"><label for="method">Payment method</label><select id="method" name="method"><option>Cash</option><option>GCash</option><option>Bank transfer</option></select></div><div class="notice">${icon('LockKeyhole')}<span>Cash requires an open shared drawer. Electronic payments stay separate from cash on hand.</span></div>${error}<div class="form-buttons"><button class="hms-btn primary">Record payment</button>${button('Drawer count','cash-close')}</div></form>`);}else if(data.shift.open){right=panel('Count & close drawer','Count the physical cash before ending the shift.',`<form id="close-form">${field('Physical cash counted (PHP)','counted','','number','min="0" step="0.01" required')}<dl class="key-values"><div><dt>Expected cash</dt><dd>${money(expected())}</dd></div><div><dt>Variance</dt><dd id="cash-variance">Enter physical count</dd></div></dl>${field('Count note / variance explanation','count-note','','text','placeholder="Required when the count differs"')}<div class="notice">${icon('CircleHelp')}<span>A difference stays visible in the shift record for review.</span></div>${error}<div class="form-buttons"><button class="hms-btn primary">Close shared drawer</button></div></form>`);}else{right=panel('Drawer is closed','Open the next shift before collecting cash.',`<div class="notice good">${icon('CircleCheck')}<span>Last close: ${money(data.shift.counted)} counted · ${money(data.shift.variance)} variance. ${esc(data.shift.note||'Balanced count.')}</span></div><form id="open-form">${field('Next opening float (PHP)','float',1000,'number','min="0" step="0.01" required')}${error}<div class="form-buttons"><button class="hms-btn primary">Open next shift</button></div></form>`);}
  return heading('Cash & billing','Keep collections, guest balances and the shared drawer in agreement.',button('Collect payment','collect','primary'))+metrics([[money(expected()),'Expected cash in current drawer'],[money(data.payments.filter(p=>p.method==='Cash'&&p.shift===data.shift.id).reduce((s,p)=>s+p.amount,0)),'Cash collected this shift'],[money(data.payments.reduce((s,p)=>s+p.amount,0)),'All preview collections today']])+`<div class="split"><div class="stack">${panel('Guest folios','Balances update after a recorded collection.',`<div class="table-wrap"><table><thead><tr><th>Guest</th><th>Charges</th><th>Balance</th><th>Action</th></tr></thead><tbody>${data.guests.map((g,i)=>`<tr><td><b>${g.name}</b><small>Room ${g.room}</small></td><td class="numeric">${money(g.total)}</td><td class="numeric">${balance(i)?money(balance(i)):badge('Settled','good')}</td><td>${balance(i)?button('Collect','collect','','data-index="'+i+'"'):'—'}</td></tr>`).join('')}</tbody></table></div>`)}${panel('Collections today','Each saved payment has a retrievable sample receipt.',`<ul class="history">${data.payments.slice().reverse().map((p,j)=>`<li>${icon('ReceiptText')}<div><b>${money(p.amount)} · ${data.guests[p.guest].name}</b><small>${p.method} · Receipt PV-${String(data.payments.length-j).padStart(4,'0')}</small></div>${button('Receipt','receipt','','data-index="'+(data.payments.length-j-1)+'"')}</li>`).join('')}</ul>`)}</div><div class="stack">${right}${checks(failCheck+button('Preview safe payment retry','retry-payment'))}</div></div>`;}
  function guests(){const p=data.profile;return heading('Guest profile & identity','One guest record, consistent account details and a clear ID review result.',badge('Front desk view','blue'))+`<div class="split"><div class="stack">${panel('Guest details','Changes save to the guest profile and account together.',`<div class="profile-heading"><div class="profile-avatar">LC</div><div><h3>${esc(p.name)}</h3><p>Guest G-0024 · In house · Room 204</p></div></div>${guestEdit?`<form id="profile-form">${field('Full name','full-name',p.name,'text','required')}${field('Mobile number','phone',p.phone,'tel','required')}${field('Address','address',p.address,'text','required')}${error}<div class="form-buttons"><button class="hms-btn primary">Save guest & account</button>${button('Cancel','cancel-profile')}</div></form>`:`<dl class="key-values"><div><dt>Mobile</dt><dd>${esc(p.phone)}</dd></div><div><dt>Email</dt><dd>${p.email}</dd></div><div><dt>Address</dt><dd>${esc(p.address)}</dd></div><div><dt>Account display name</dt><dd>${esc(p.name)}</dd></div></dl><div class="form-buttons">${button('Edit profile','edit-profile')}</div>`}`)}${panel('Current reservation','The original reservation name remains in the booking history.',`<dl class="key-values"><div><dt>Reservation</dt><dd>RSV-1024</dd></div><div><dt>Name on reservation</dt><dd>Lara Cruz</dd></div><div><dt>Stay</dt><dd>Nov 2–5, 2026 · Room 204</dd></div></dl>`)}${panel('Activity','Trace who changed the record.',data.audit.length?`<ul class="history">${data.audit.map(x=>`<li>${icon('Check')}<div><b>${esc(x)}</b><small>Alex Reyes · just now</small></div></li>`).join('')}</ul>`:'<p class="muted">No changes made in this preview.</p>')}</div><div class="stack">${panel('Identity review','RSV-1024 · document belongs to this guest.',`<div class="review-document">${icon('FileText')}<b>Sample upload</b><span>No personal identification is displayed</span></div><dl class="key-values"><div><dt>Guest identity</dt><dd>${badge(data.verified?'Verified':'Pending review',data.verified?'good':'warn')}</dd></div><div><dt>Uploaded document</dt><dd>${badge(data.verified?'Verified':'Pending review',data.verified?'good':'warn')}</dd></div></dl><div class="notice">${icon('ShieldCheck')}<span>Both review statuses change together after the reviewer checks the document.</span></div>${error}<div class="form-buttons">${button(data.verified?'Verified by Alex Reyes':'Verify document & guest','verify',data.verified?'':'primary',data.verified?'disabled':'')}</div>`)}${checks(failCheck+button('Simulate replacement upload','replace-id'))}</div></div>`;}
  function requests(){const rows=guestView?data.requests.filter(r=>r.detail.includes('Lara Cruz')):data.requests;return heading('Guest requests','A clear next step for the guest and the department handling the work.',button(guestView?'View as front desk':'Preview guest view','guest-view'))+`<div class="section-tabs">${button('Guest requests','requests-tab','active')}${button('Operational handover','handover-tab')}</div><div class="split"><div class="stack">${panel(guestView?'My requests':'Request queue',guestView?'Lara Cruz · Room 204 · guest-facing preview':'Pending requests need front desk review.',rows.map((r)=>`<article class="request-item"><div class="request-top"><div><small>${r.id}</small><h3>${r.title}</h3><p>${r.detail}</p></div>${badge(r.status,r.status==='Pending'?'warn':r.status==='Completed'?'good':'')}</div><div class="request-bottom"><span>Responsible: ${r.owner}</span>${r.status==='Pending'?(guestView?button('Withdraw request','withdraw','','data-id="'+r.id+'"'):button('Accept & route','accept','primary','data-id="'+r.id+'"')):r.status==='In progress'&&guestView?'<span>Contact front desk to change this request.</span>':''}</div><div id="confirm-${r.id}" class="request-confirm" hidden><p>Withdraw this pending request? The team will no longer process it.</p>${button('Yes, withdraw','confirm-withdraw','danger','data-id="'+r.id+'"')}${button('Keep request','keep-request','','data-id="'+r.id+'"')}</div></article>`).join(''))}</div><div class="stack">${panel('How requests move','Ownership remains visible at every stage.',`<ul class="history"><li>${icon('Clock3')}<div><b>Pending</b><small>The guest can withdraw before acceptance.</small></div></li><li>${icon('ClipboardCheck')}<div><b>Accepted & routed</b><small>The assigned department takes responsibility.</small></div></li><li>${icon('CheckCheck')}<div><b>Completed</b><small>Completion stays in request history.</small></div></li></ul><div class="notice">${icon('CircleHelp')}<span>Cancelled requests cannot be accepted or fulfilled. Supply completion must save with the related stock movement.</span></div>`)}${checks(failCheck)}<p id="form-error" class="inline-error" role="alert" hidden></p></div></div>`;}
  function handover(){return heading('Operational handover','Give unfinished hotel work a named owner before the shift changes.',badge('Front desk view','blue'))+`<div class="section-tabs">${button('Guest requests','requests-tab')}${button('Operational handover','handover-tab','active')}</div><div class="split"><div class="stack">${panel('Handover log',`${data.handovers.filter(h=>h.status!=='Resolved').length} open follow-ups · source records stay linked`,data.handovers.map(h=>`<article class="request-item"><div class="request-top"><div><small>${h.id} · ${h.source}</small><h3>${esc(h.title)}</h3><p>${esc(h.note)}</p></div>${badge(h.status,h.status==='Resolved'?'good':h.status==='Awaiting acknowledgement'?'warn':'blue')}</div><div class="request-bottom"><span>Assigned to ${esc(h.owner)}</span>${h.status==='Awaiting acknowledgement'?button('Acknowledge','ack','','data-id="'+h.id+'"'):h.status==='Acknowledged'?button('Record resolution','resolve','','data-id="'+h.id+'"'):''}</div><form class="resolve-form" data-id="${h.id}" id="resolve-${h.id}" hidden>${field('Resolution note','resolution-'+h.id,'','text','required')}<button class="hms-btn primary">Resolve follow-up</button></form></article>`).join(''))}</div><div class="stack">${panel('Create handover','Assign an operational follow-up within the department.',`<form id="handover-form"><div class="field"><label for="source">Source record</label><select name="source" id="source"><option>RSV-1027</option><option>GR-1038</option><option>RSV-1024</option></select></div>${field('Follow-up title','title','','text','required placeholder="e.g. Confirm guest arrival time"')}<div class="field"><label for="note">Handover note</label><textarea name="note" id="note" rows="3" required></textarea></div><div class="field"><label for="owner">Receiving staff</label><select name="owner" id="owner"><option>Nina Morales · Front desk</option><option>Alex Reyes · Front desk</option></select></div>${error}<div class="form-buttons"><button class="hms-btn primary">Create handover</button></div></form>`)}<div class="notice">${icon('CircleHelp')}<span>Acknowledgement confirms receipt. Resolving this follow-up does not automatically complete its source request or reservation.</span></div>${checks(failCheck)}</div></div>`;}
  function render(){ $('#workflow-content').innerHTML=({stock,cash,guests,requests,handover}[screen]||stock)(); document.querySelectorAll('[data-screen]').forEach(el=>{let active=el.dataset.screen===screen||(el.closest('.workflow-switcher')&&screen==='handover'&&el.dataset.screen==='requests');el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});$('#header-title').textContent=({stock:'Inventory',cash:'Cash & Shifts',guests:'Guests',requests:guestView?'Guest requests':'Guest Requests',handover:'Operational Handover'})[screen];$('#account-name').textContent=screen==='stock'?'Mara Santos':guestView&&screen==='requests'?'Lara Cruz':'Alex Reyes';$('#account-avatar').textContent=screen==='stock'?'MS':guestView&&screen==='requests'?'LC':'AR';$('#account-role').textContent=(screen==='stock'?'Housekeeping':guestView&&screen==='requests'?'Guest':'Front desk')+' · preview';$('#header-shift').innerHTML=icon('Clock3')+(data.shift.open?' Shared drawer open':' Shared drawer closed'); }
  function navigate(next){screen=next;selected=next==='stock'?1:0;cashMode='close';guestEdit=false;render();$('.hms-preview').classList.remove('mobile-nav-open');$('#nav-scrim').hidden=true;}
  document.addEventListener('click',event=>{const route=event.target.closest('[data-screen]');if(route){navigate(route.dataset.screen);return;}if(event.target.closest('[data-placeholder]')){toast('Dashboard shell placeholder — explore the four workflow tabs above.');return;}const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;let r=data.requests.find(x=>x.id===id),h=data.handovers.find(x=>x.id===id);switch(action){case'select-stock':selected=Number(el.dataset.index);render();break;case'insufficient':$('#quantity').value=data.stock[selected].qty+1;$('#quantity').focus();toast('Submit this quantity to preview the stock safeguard.');break;case'fail':data.fail=true;toast('The next save will fail safely. Submit a form to see the preserved draft.');break;case'retry-stock':case'retry-payment':toast(data.last?'Proposed retry behavior: return the original result without recording it twice. This control only illustrates the safeguard.':'Save a movement or payment first.');break;case'collect':selected=Number(el.dataset.index||0);cashMode='collect';render();break;case'cash-close':cashMode='close';render();break;case'receipt':{const p=data.payments[Number(el.dataset.index)],d=$('#receipt-dialog');d.innerHTML=`<header><div><h2 id="receipt-title">Payment receipt</h2><small>PREVIEW ONLY · Not an official receipt</small></div><button class="close-receipt" aria-label="Close receipt">${icon('X')}</button></header><dl><div><dt>Guest</dt><dd>${data.guests[p.guest].name}</dd></div><div><dt>Method</dt><dd>${p.method}</dd></div><div class="receipt-total"><dt>Amount paid</dt><dd>${money(p.amount)}</dd></div><div><dt>Remaining balance</dt><dd>${money(balance(p.guest))}</dd></div></dl>`;d.showModal();d.querySelector('button').onclick=()=>d.close();break;}case'edit-profile':guestEdit=true;render();break;case'cancel-profile':guestEdit=false;render();break;case'verify':if(saveAllowed()){data.verified=true;data.audit.unshift('Guest and uploaded document verified together');render();toast('Identity and document status updated together.');}break;case'replace-id':data.verified=false;data.audit.unshift('Replacement upload received — a new review is required');render();toast('Both statuses returned to pending review.');break;case'guest-view':guestView=!guestView;render();break;case'requests-tab':navigate('requests');break;case'handover-tab':navigate('handover');break;case'withdraw':$('#confirm-'+id).hidden=false;break;case'keep-request':$('#confirm-'+id).hidden=true;break;case'confirm-withdraw':if(r.status==='Pending'&&saveAllowed()){r.status='Withdrawn';r.owner='No active assignment';render();toast('Pending request withdrawn.');}break;case'accept':if(r.status==='Pending'&&saveAllowed()){r.status='In progress';r.owner='Housekeeping';render();toast('Request accepted and routed to Housekeeping.');}break;case'ack':if(saveAllowed()){h.status='Acknowledged';render();toast('Handover acknowledged.');}break;case'resolve':$('#resolve-'+id).hidden=false;break;}});
  document.addEventListener('input',e=>{if(e.target.id==='counted')$('#cash-variance').textContent=e.target.value===''?'Enter physical count':money(Number(e.target.value)-expected());});
  document.addEventListener('change',e=>{if(e.target.id==='guest'){selected=Number(e.target.value);$('#amount').value=balance(selected);}});
  document.addEventListener('submit',e=>{if(!e.target.closest('#workflow-content'))return;e.preventDefault();const form=e.target,f=new FormData(form);if(form.id==='stock-form'){const qty=Number(f.get('quantity')),item=data.stock[selected],count=f.get('kind')==='count';if(!Number.isInteger(qty)||qty<0||(!count&&qty===0))return formError('Enter a valid whole quantity.');if(!count&&qty>item.qty)return formError(`Only ${item.qty} ${item.unit} are available. No stock or history was changed.`);if(!saveAllowed())return;const before=item.qty;item.qty=count?qty:item.qty-qty;data.movements.push({title:`${item.name}: ${before} → ${item.qty}`,detail:`${count?'Count correction':'Issue'} · ${f.get('reference')} · ${f.get('reason')}`});data.last='stock';render();toast('Stock balance and movement history saved together.');}else if(form.id==='payment-form'){const g=Number(f.get('guest')),amount=Number(f.get('amount')),method=f.get('method');if(amount<=0||amount>balance(g))return formError('Enter an amount above zero and no greater than the outstanding balance.');if(method==='Cash'&&!data.shift.open)return formError('Open a shared drawer before collecting cash. Your payment has not been recorded.');if(!saveAllowed())return;data.payments.push({guest:g,amount,method,shift:data.shift.id});data.last='payment';render();toast('Payment, folio balance and sample receipt saved together.');}else if(form.id==='close-form'){const counted=Number(f.get('counted')),variance=counted-expected(),note=String(f.get('count-note')).trim();if(variance!==0&&!note)return formError('Explain the cash difference before closing the drawer.');if(!saveAllowed())return;Object.assign(data.shift,{open:false,counted,variance,note});render();toast('Drawer closed. The count and variance remain in the shift record.');}else if(form.id==='open-form'){if(!saveAllowed())return;data.shift={id:data.shift.id+1,float:Number(f.get('float')),open:true};render();toast('New shift opened with its own starting float.');}else if(form.id==='profile-form'){if(!saveAllowed())return;Object.assign(data.profile,{name:String(f.get('full-name')).trim(),phone:String(f.get('phone')).trim(),address:String(f.get('address')).trim()});data.audit.unshift('Guest profile and account details saved together');guestEdit=false;render();toast('Guest and account updated. Booking history preserved.');}else if(form.id==='handover-form'){if(!saveAllowed())return;data.handovers.unshift({id:'HO-'+String(13+data.handovers.length-2).padStart(3,'0'),title:String(f.get('title')).trim(),note:String(f.get('note')).trim(),source:f.get('source'),owner:f.get('owner'),status:'Awaiting acknowledgement'});render();toast('Follow-up created with a named receiving staff member.');}else if(form.classList.contains('resolve-form')){const h=data.handovers.find(x=>x.id===form.dataset.id);h.status='Resolved';h.note+=' Resolution: '+String(f.get('resolution-'+h.id)).trim();render();toast('Follow-up resolved. Source record unchanged.');}});
  $('#collapse-sidebar').onclick=()=>{const collapsed=$('.hms-preview').classList.toggle('sidebar-collapsed');$('.sidebar').classList.toggle('collapsed',collapsed);$('#collapse-sidebar').setAttribute('aria-expanded',String(!collapsed));};$('.brand-mark').onclick=()=>{if($('.hms-preview').classList.contains('sidebar-collapsed'))$('#collapse-sidebar').click();};$('#mobile-menu').onclick=()=>{$('.hms-preview').classList.add('mobile-nav-open');$('#nav-scrim').hidden=false;};$('#nav-scrim').onclick=()=>{$('.hms-preview').classList.remove('mobile-nav-open');$('#nav-scrim').hidden=true;};document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#nav-scrim').click();});$('#theme-toggle').onclick=()=>{const light=document.documentElement.classList.toggle('theme-light');$('#theme-toggle').innerHTML=icon(light?'Moon':'Sun');$('#theme-toggle').setAttribute('aria-label',light?'Preview dark theme':'Preview light theme');};$('#reset-demo').onclick=()=>{data=initial();guestView=false;selected=1;cashMode='close';guestEdit=false;render();toast('All sample records reset.');};$('#toggle-notes').onclick=()=>{const el=$('#design-notes');el.hidden=!el.hidden;$('#toggle-notes').setAttribute('aria-expanded',String(!el.hidden));};$('#design-notes').innerHTML='<b>What this proposal changes</b><ul><li>Stock: one operation for quantity and movement history, with insufficient-stock protection.</li><li>Cash: visible drawer count, variance explanation and connected payment/folio/receipt results.</li><li>Guests: consistent profile/account saving and paired guest/document review statuses.</li><li>Operations: controlled request withdrawal, explicit ownership and acknowledged handovers.</li></ul><p>This is a client-side design prototype. It demonstrates intended outcomes, not production permissions, database atomicity or concurrency guarantees. The existing dashboard shell is retained. HR, procurement and enterprise finance are outside this preview.</p>';
  render();
})();
